function renderSummaryReport(){const label=modeLabel(),rows=filteredRows,s=stats(rows),st=status(rows),verify=verificationForMode();$('summaryTitle').textContent=`${label} Summary & Conclusion Report`;$('summarySubtitle').textContent='Generated from validated data, the selected analysis mode and the active filters.';if(!rows.length||!s.N){$('executiveSummary').textContent='No valid Present marks are available for the current mode and filters.';$('summaryVerification').innerHTML='<span class="verifyBad">NO ANALYZABLE DATA</span>';$('summaryFindings').innerHTML='';$('summaryTopGroups').innerHTML='';$('summaryLowGroups').innerHTML='';$('summaryQuality').innerHTML='';$('summaryConclusion').textContent='Load valid assessment data or change the active filters to generate a conclusion.';$('summaryRecommendations').textContent='No recommendation is generated without valid Present marks.';return}const uniqueStudents=new Set(rows.map(r=>r.REG_NO).filter(Boolean)).size,courses=new Set(rows.map(r=>r.COURSE_CODE).filter(Boolean)).size,faculty=new Set(rows.map(r=>r.ERP_ID||r.FACULTY_NAME).filter(Boolean)).size,classes=new Set(rows.map(r=>r.CLASS_ID).filter(Boolean)).size,presentPct=rows.length?100*s.N/rows.length:0,variability=s.cv<15?'low':s.cv<30?'moderate':'high',shape=skewText(s.skew),kshape=kurtText(s.kurtosis),g=gradeDist(rows);let failPct=0,upperPct=0;if(g){failPct=100*g.counts.F/g.s.N;upperPct=100*(g.counts.S+g.counts.A)/g.s.N}let combinedText='',pairStats=null;if(analysisMode==='combined'){pairStats=pearsonPairs(rows);const cmp=rows.filter(r=>r.BOTH_PRESENT),imp=cmp.filter(r=>r.DIFFERENCE_PP>0).length,dec=cmp.filter(r=>r.DIFFERENCE_PP<0).length,same=cmp.filter(r=>r.DIFFERENCE_PP===0).length;combinedText=` Among ${cmp.length.toLocaleString()} valid matched pairs, ${imp.toLocaleString()} improved, ${dec.toLocaleString()} declined and ${same.toLocaleString()} were unchanged on normalized percentage.`}$('executiveSummary').textContent=`${label} analysis contains ${rows.length.toLocaleString()} validated records representing ${uniqueStudents.toLocaleString()} students across ${courses} courses, ${faculty} faculty and ${classes} classes. ${s.N.toLocaleString()} records have valid Present marks. Mean mark is ${f(s.mean)}, mean normalized score is ${f(s.meanPct)}%, median is ${f(s.median)}, and population SD is ${f(s.sd)}. The central 50% lies from Q1 ${f(s.q1)} to Q3 ${f(s.q3)}.${combinedText}`;$('summaryVerification').innerHTML=`<span class="${verify.ok?'verifyGood':'verifyBad'}">${escapeHtml(verify.status)}</span><p class="subcap" style="margin-top:10px">${escapeHtml(verify.details)}</p>`;const findings=[findingCard('Valid Present N',s.N.toLocaleString(),`${f(presentPct)}% of current rows`),findingCard('Mean mark / Mean %',`${f(s.mean)} / ${f(s.meanPct)}%`,'Raw and normalized central tendency'),findingCard('Median / Mode',`${f(s.median)} / ${s.mode}`,'Robust center and most frequent mark'),findingCard('Population / Sample SD',`${f(s.sd)} / ${f(s.sampleSd)}`,`${variability} relative variability; CV ${f(s.cv)}%`),findingCard('P10 - P90',`${f(s.p10)} - ${f(s.p90)}`,'Middle 80% reference range'),findingCard('Q1 - Q3 / IQR',`${f(s.q1)} - ${f(s.q3)} / ${f(s.iqr)}`,'Central 50% spread'),findingCard('Skewness',f(s.skew,3),shape),findingCard('Excess kurtosis',f(s.kurtosis,3),kshape),findingCard('Tukey outliers',`${s.outliers} (${f(100*s.outliers/s.N)}%)`,'Review observations; do not auto-delete'),findingCard('Proposed F share',`${f(failPct)}%`,'What-if grade scenario only'),findingCard('Proposed S + A share',`${f(upperPct)}%`,'What-if grade scenario only')];if(pairStats){findings.push(findingCard('CAT-I / CAT-II correlation',f(pairStats.corr,3),'Pearson correlation on matched normalized scores'),findingCard('Mean CAT-II - CAT-I change',`${f(pairStats.meanDiff)} pp`,'Percentage-point change among valid pairs'))}$('summaryFindings').innerHTML=findings.join('');const groups=groupSummary().filter(r=>r.N>=5&&r.MeanPct!==null),top=groups.slice(0,5),low=[...groups].sort((a,b)=>(a.MeanPct??999)-(b.MeanPct??999)).slice(0,5),groupLabel=groupMode==='course'?'Course':groupMode==='faculty'?'Faculty':'Class';const mini=arr=>arr.length?`<table class="miniTable"><thead><tr><th>${groupLabel}</th><th>N</th><th>Mean %</th><th>SD</th></tr></thead><tbody>${arr.map(r=>`<tr><td>${escapeHtml(r.Level)}</td><td>${r.N}</td><td>${f(r.MeanPct)}</td><td>${f(r.SD)}</td></tr>`).join('')}</tbody></table>`:'No groups with N >= 5 available.';$('summaryTopGroups').innerHTML=mini(top);$('summaryLowGroups').innerHTML=mini(low);const cr=cleaningReport;$('summaryQuality').innerHTML=table([{Item:'Input rows',Value:cr.inputRows||0,Meaning:'Rows read from the selected source files.'},{Item:'Validated rows',Value:cr.cleanRows||0,Meaning:'Rows available for analysis after validation controls.'},{Item:'Exact duplicate rows excluded',Value:cr.exactDuplicatesRemoved||0,Meaning:'Identical duplicate rows excluded from calculations.'},{Item:'Duplicate analytical keys',Value:cr.duplicateKeys||0,Meaning:'Repeated MARK_MODE + student + course + class keys retained for review.'},{Item:'Invalid marks',Value:cr.invalidMarks||0,Meaning:'Excluded from score statistics.'},{Item:'Missing Present marks',Value:cr.missingPresentMarks||0,Meaning:'Excluded from score statistics.'},{Item:'Unsupported MARK_MODE',Value:cr.unsupportedModes||0,Meaning:'Excluded from CAT-I/CAT-II analysis.'}],[['Item','Item'],['Value','Value'],['Meaning','Meaning']]);let conclusion=`The ${label} result has a mean normalized score of ${f(s.meanPct)}% with ${variability} relative dispersion (CV ${f(s.cv)}%). The score distribution is ${shape} and ${kshape}. Tukey's rule flags ${s.outliers} observations (${f(100*s.outliers/s.N)}%) as statistical outliers; these are review points, not automatic data errors.`;if(analysisMode==='combined'&&pairStats)conclusion+=` Matched CAT-I/CAT-II scores have Pearson correlation ${f(pairStats.corr,3)} and an average CAT-II minus CAT-I change of ${f(pairStats.meanDiff)} percentage points.`;conclusion+=` The current relative-grade scenario places ${f(failPct)}% in F and ${f(upperPct)}% in S/A using configurable mean/SD boundaries on normalized percentages. These are analytical scenarios and must not be treated as official grades without the institution's approved grading policy.`;$('summaryConclusion').textContent=conclusion;const notes=[];if(!verify.ok)notes.push('Resolve validation warnings before using results for academic decisions.');if(cleaningReport.exactDuplicatesRemoved)notes.push(`${cleaningReport.exactDuplicatesRemoved} exact duplicate row(s) were removed automatically; review the data-quality summary for auditability.`);if(s.cv>=30)notes.push('High relative variability suggests inspecting course/class distributions and outliers before using a single mean/SD boundary scheme.');if(s.skew!==null&&Math.abs(s.skew)>=1)notes.push('Strong skewness means percentile-based review may complement mean/SD grading.');if(s.outliers/s.N>.05)notes.push('More than 5% of valid marks are outside Tukey fences; inspect these records and the assessment design before interpretation.');if(analysisMode==='combined')notes.push('Combined results use only valid matched CAT-I/CAT-II Present records and normalized percentages with the configured weights.');notes.push('Faculty/course/class comparisons are descriptive; differences may reflect cohort composition, course difficulty, assessment design and class size.');notes.push('Do not infer teaching quality or causality from mean marks alone.');notes.push('Official grade decisions should remain separate from statistical suggestions and require authorized academic review.');$('summaryRecommendations').innerHTML=`<ul class="summaryList">${notes.map(x=>`<li>${escapeHtml(x)}</li>`).join('')}</ul>`;$('summaryStamp').textContent=`Mode: ${label} | Grouping: ${groupLabel} | Analyzed rows in current view: ${rows.length.toLocaleString()} | Generated: ${new Date().toLocaleString()}`}
function downloadSummaryReport(){if(!filteredRows.length){alert('Analyze data first.');return}renderSummaryReport();const label=modeLabel(),body=$('summaryReport').innerHTML;const html=`<!doctype html><html><head><meta charset="utf-8"><title>${label} Summary & Conclusion Report</title><style>body{font-family:Segoe UI,Arial,sans-serif;color:#172033;margin:28px}h1,h2,h3{color:#17345e}.summaryHero,.grid2{display:grid;grid-template-columns:1fr 1fr;gap:12px}.summaryCard,.panel{border:1px solid #dbe3ef;border-radius:10px;padding:14px;margin-bottom:12px}.findingGrid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.finding{border:1px solid #dbe3ef;border-radius:8px;padding:10px}.finding .t{font-size:12px;color:#667085}.finding .v{font-size:18px;font-weight:700}.verifyGood{color:#14623f;font-weight:700}.verifyBad{color:#9a241d;font-weight:700}.conclusionBox,.recommendBox{padding:12px;border:1px solid #dbe3ef;border-radius:8px;line-height:1.6}.miniTable,table{width:100%;border-collapse:collapse}.miniTable th,.miniTable td,th,td{border-bottom:1px solid #dbe3ef;padding:7px;text-align:left;font-size:12px}.caption{font-size:22px;font-weight:800}.subcap,.reportStamp{color:#667085;font-size:12px;margin-bottom:12px}.developerCredit{margin-top:18px;padding-top:10px;border-top:1px solid #dbe3ef;text-align:center;font-size:12px;color:#536078;font-weight:600}.tablewrap{overflow:visible;max-height:none}@media print{body{margin:10mm}.summaryCard,.panel{break-inside:avoid}}</style></head><body>${body}</body></html>`;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([html],{type:'text/html'}));a.download=`${label.replaceAll(' ','_')}_Summary_Conclusion_Report.html`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
