function exportCSV(){if(!filteredRows.length){alert('Analyze data first.');return}downloadCsv(filteredRows,`${modeLabel().replaceAll(' ','_')}_analysis.csv`)}
function downloadCsv(rows,name){const cols=[...new Set(rows.flatMap(r=>Object.keys(r)))].filter(c=>!['_RAW_MARK_MODE','_RAW_STATUS'].includes(c));const csv=[cols.join(','),...rows.map(r=>cols.map(c=>'"'+String(r[c]??'').replaceAll('"','""')+'"').join(','))].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function analyze(){const files=[...$('files').files];if(!files.length){alert('Select at least one Excel or CSV result file.');return}try{$('analyzeBtn').textContent='Analyzing…';const batches=[];for(const file of files)batches.push(await readFile(file));rawRows=batches.flat();const cleaned=cleanDataset(rawRows);allRows=cleaned.rows;cleaningReport=cleaned.report;cat1=allRows.filter(r=>r.MARK_MODE==='CAT1');cat2=allRows.filter(r=>r.MARK_MODE==='CAT2');otherModes=allRows.filter(r=>r.MARK_MODE!=='CAT1'&&r.MARK_MODE!=='CAT2');pairData();$('fileMeta').innerHTML=`${files.length} file(s) — ${rawRows.length.toLocaleString()} input rows → <b>${allRows.length.toLocaleString()} validated rows</b>. CAT1: <b>${cat1.length.toLocaleString()}</b>, CAT2: <b>${cat2.length.toLocaleString()}</b>, Other: <b>${otherModes.length.toLocaleString()}</b>`;$('detectedModes').innerHTML=`<span>CAT1: <b>${cat1.length.toLocaleString()}</b></span><span>CAT2: <b>${cat2.length.toLocaleString()}</b></span><span>Other: <b>${otherModes.length.toLocaleString()}</b></span>`;if(analysisMode==='cat1'&&!cat1.length)alert('No MARK_MODE=CAT1 rows were found. Choose CAT-II mode or load CAT1 data.');if(analysisMode==='cat2'&&!cat2.length)alert('No MARK_MODE=CAT2 rows were found. Choose CAT-I mode or load CAT2 data.');if(analysisMode==='combined'&&(!cat1.length||!cat2.length))alert('Combined mode requires both MARK_MODE=CAT1 and MARK_MODE=CAT2 rows.');populateFilters();applyFilters()}catch(e){console.error(e);alert('Unable to analyze: '+e.message)}finally{$('analyzeBtn').textContent='Analyze'}}
function switchMode(mode){analysisMode=mode;document.querySelectorAll('[data-analysis-mode]').forEach(b=>b.classList.toggle('active',b.dataset.analysisMode===mode));$('combinedControls').classList.toggle('show',mode==='combined');$('modeStatus').textContent=mode==='cat1'?'CAT-I mode':mode==='cat2'?'CAT-II mode':'Combined mode';populateFilters();if((mode==='cat1'&&cat1.length)||(mode==='cat2'&&cat2.length)||(mode==='combined'&&cat1.length&&cat2.length))applyFilters();else{filteredRows=[];renderAll()}}
$('analyzeBtn').addEventListener('click',analyze);$('csvBtn').addEventListener('click',exportCSV);$('pdfBtn').addEventListener('click',exportPdfReport);$('summaryDownloadBtn').addEventListener('click',downloadSummaryReport);$('gradeBtn').addEventListener('click',renderGrades);['courseFilter','facultyFilter','classFilter'].forEach(id=>$(id).addEventListener('change',applyFilters));$('studentSearch').addEventListener('input',applyFilters);['w1','w2'].forEach(id=>$(id).addEventListener('change',()=>{if(analysisMode==='combined'&&cat1.length&&cat2.length){populateFilters();applyFilters()}}));document.querySelectorAll('[data-analysis-mode]').forEach(b=>b.addEventListener('click',()=>switchMode(b.dataset.analysisMode)));document.querySelectorAll('.tabbtn').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.tabbtn').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));$(b.dataset.view).classList.add('active')}));document.querySelectorAll('[data-group]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-group]').forEach(x=>x.classList.remove('active'));b.classList.add('active');groupMode=b.dataset.group;renderAnalysis();renderSummaryReport()}));$('toggleAnalysisTable').addEventListener('click',e=>{const p=$('analysisTablePanel');p.classList.toggle('hidden');e.target.textContent=p.classList.contains('hidden')?'Show Table':'Hide Table'});$('toggleAnalysisChart').addEventListener('click',e=>{const p=$('analysisChartPanel');p.classList.toggle('hidden');e.target.textContent=p.classList.contains('hidden')?'Show Chart':'Hide Chart'});

